notes.body:
I've cleaned up a bit the scripts I've used to generate my test pcaps. I will put them here to make it easier to generate specific message if I've missed any.

Setup tables:
```
CREATE TABLE IF NOT EXISTS table_identity_key(id int PRIMARY KEY, data text);
CREATE TABLE IF NOT EXISTS table_identity_full(id int PRIMARY KEY, data text);
ALTER table table_identity_full replica identity full;

CREATE TABLE stream_test(data text);
alter table stream_test replica identity full;

-- To test type messages
CREATE TYPE test_type AS ENUM ('new', 'open', 'closed');
CREATE TABLE IF NOT EXISTS test_type_table(data text, ty test_type);

-- To test unchanged toast
CREATE TABLE IF NOT EXISTS xpto (id serial primary key, toasted_col1 text, toasted_col2 text);

CREATE PUBLICATION all_tables for all tables;
-- Lower decoding mem to force txn streaming
ALTER SYSTEM SET logical_decoding_work_mem='64kB';
-- This requires a restart
ALTER SYSTEM SET max_prepared_transactions=1;
SELECT pg_reload_conf();
```

PG needs to be restarted. Then, a logical stream can be started using `pg_recvlogical`:
pg_recvlogical -d postgres --slot=test -oproto_version=4 -opublication_names=all_tables -omessages=true -ostreaming=parallel --start -f -


Running those queries will generate at least one logical replication message of each type between  pg_recvlogical and PG:
```
SELECT pg_replication_origin_create('test_origin');
SELECT pg_replication_origin_session_setup('test_origin');

-- Type message
INSERT INTO test_type_table VALUES('a', 'new'::test_type);

SELECT pg_replication_origin_session_reset();
SELECT pg_replication_origin_drop('test_origin');

-- Replica identity key
INSERT INTO table_identity_key SELECT generate_series(1, 5);
UPDATE table_identity_key SET id=20 WHERE id=1;
UPDATE table_identity_key SET data='Update non key';
DELETE FROM table_identity_key WHERE id < 3;
BEGIN;
UPDATE table_identity_key SET data='2PC' where id=3;
PREPARE TRANSACTION 'test';
COMMIT PREPARED 'test';
TRUNCATE table_identity_key;
BEGIN;
INSERT INTO table_identity_key SELECT generate_series(1, 5);
ROLLBACK;

-- Replica identity full
INSERT INTO table_identity_full SELECT generate_series(1, 5);
UPDATE table_identity_full SET id=20 WHERE id=1;
UPDATE table_identity_full SET data='Update non key';
DELETE FROM table_identity_full WHERE id < 3;
TRUNCATE table_identity_full;
BEGIN;
UPDATE table_identity_full SET data='2PC' where id=3;
PREPARE TRANSACTION 'test';
COMMIT PREPARED 'test';
TRUNCATE table_identity_full;
BEGIN;
INSERT INTO table_identity_full SELECT generate_series(1, 5);
ROLLBACK;

-- Streaming test, this requires setting logical_decoding_work_mem to 64KB
INSERT INTO stream_test SELECT repeat('a', 6000) || g.i FROM generate_series(1, 10) g(i);
BEGIN;
savepoint s1;
SELECT 'msg5' FROM pg_logical_emit_message(true, 'test', repeat('a', 50));
INSERT INTO stream_test SELECT repeat('a', 2000) || g.i FROM generate_series(1, 35) g(i);
TRUNCATE table stream_test;
rollback to s1;
INSERT INTO stream_test SELECT repeat('a', 10) || g.i FROM generate_series(1, 20) g(i);
COMMIT;
BEGIN;
SAVEPOINT s1;
SELECT 'msg5' FROM pg_logical_emit_message(true, 'test', repeat('a', 50));
INSERT INTO stream_test SELECT repeat('a', 2000) || g.i FROM generate_series(1, 35) g(i);
TRUNCATE table stream_test;
ROLLBACK TO s1;
INSERT INTO stream_test SELECT repeat('a', 10) || g.i FROM generate_series(1, 20) g(i);
PREPARE TRANSACTION 'test1';
COMMIT PREPARED 'test1';

-- uncompressed external toast data
INSERT INTO xpto (id, toasted_col1, toasted_col2) SELECT 1, string_agg(g.i::text, ''), string_agg((g.i*2)::text, '') FROM generate_series(1, 2000) g(i);
-- compressed external toast data
INSERT INTO xpto (id, toasted_col2) SELECT 2, repeat(string_agg(to_char(g.i, 'FM0000'), ''), 50) FROM generate_series(1, 500) g(i);
-- update of existing column
UPDATE xpto SET toasted_col1 = (SELECT string_agg(g.i::text, '') FROM generate_series(1, 2000) g(i)) WHERE id = 1;
UPDATE xpto SET rand1 = 123.456 WHERE id = 1;
-- updating external via INSERT ... ON CONFLICT DO UPDATE
INSERT INTO xpto(id, toasted_col2) VALUES (2, 'toasted2-upsert')
ON CONFLICT (id)
DO UPDATE SET toasted_col2 = EXCLUDED.toasted_col2 || xpto.toasted_col2;
DELETE FROM xpto;
```

> Do you have a sample capture for this feature, that could be used for fuzz testing?

Here's the generated pcap from running the previous queries with `streaming=parallel` and `proto_version=4`: [logical_replication_v4.pcap.gz](/uploads/87a06a2374624439572646caeae1e068/logical_replication_v4.pcap.gz).

