+            n += 4;
+        }
+        proto_tree_add_item(shrub, hf_relation_oid, tvb, n, 4, ENC_BIG_ENDIAN);
+        n += 4;
+        n = dissect_new_tuple_data(tvb, n, shrub);
+        break;
