+            n += 4;
+        }
+        i = tvb_get_ntohl(tvb, n);
+        proto_tree_add_item_ret_uint(shrub, hf_logical_relation_number, tvb, n, 4, ENC_BIG_ENDIAN, &i);
+        n += 4;
+        proto_tree_add_item(shrub, hf_logical_truncate_flags, tvb, n, 1, ENC_BIG_ENDIAN);
+        n += 1;
